const MODULES_BY_ID = Object.fromEntries(MODULES.map(m => [m.id, m]));

// ----------------------------------------------------------------------
// State
// ----------------------------------------------------------------------

const moduleState = {
    moduleId: null,
    activity: null,            // 'lesson' | 'practice' | 'quiz'
    lessonIndex: 0,
    problemIndex: 0,
    answer: '',
    score: 0,
    streak: 0,
    bestStreak: 0,
    correct: 0,
    sessionRobux: 0,
    hintShown: false,
    locked: false,
};

const ROBUX_PER_QUIZ_CORRECT = 2;

// ----------------------------------------------------------------------
// Home — module grid
// ----------------------------------------------------------------------

// Module categories — order, emoji, title.
// Modules carry a `category` letter that maps into here.
const CATEGORIES = [
    { id: 'A', title: 'Counting & Number Sense', emoji: '🔢' },
    { id: 'B', title: 'Addition Strategies',     emoji: '➕' },
    { id: 'C', title: 'Subtraction Strategies',  emoji: '➖' },
    { id: 'D', title: 'Place Value & Big Numbers', emoji: '🔟' },
    { id: 'E', title: 'Comparing Numbers',       emoji: '⚖️' },
    { id: 'F', title: 'Telling Time',            emoji: '🕐' },
    { id: 'G', title: 'Money & Coins',           emoji: '🪙' },
    { id: 'H', title: 'Shapes (2D & 3D)',        emoji: '🔷' },
    { id: 'I', title: 'Equal Shares',            emoji: '🥧' },
    { id: 'J', title: 'Measurement',             emoji: '📏' },
    { id: 'K', title: 'Patterns',                emoji: '🌀' },
    { id: 'L', title: 'Graphs & Data',           emoji: '📊' },
    { id: 'M', title: 'Word Problems',           emoji: '📖' },
    { id: 'N', title: 'Mixed Math',              emoji: '🎯' },
];

function renderHomeModules() {
    const grid = document.getElementById('module-grid');
    if (!grid) return;

    // Default category if a module didn't get one assigned.
    const fallback = 'A';
    const byCategory = {};
    for (const m of MODULES) {
        const cat = m.category || fallback;
        (byCategory[cat] || (byCategory[cat] = [])).push(m);
    }

    const progress = (typeof loadAllProgress === 'function') ? loadAllProgress() : {};
    const visits   = (typeof loadAllVisits   === 'function') ? loadAllVisits()   : {};
    const streak   = (typeof loadStreak      === 'function') ? loadStreak()      : { current: 0, longest: 0 };
    const totalStars = Object.values(progress).reduce((sum, p) => sum + (p.stars || 0), 0);
    const completedCount = Object.keys(progress).length;
    const isHakan = (typeof currentUser !== 'undefined' && currentUser === 'hakan');

    let html = '';

    // Top row: streak, pet, trophies (Hakan only)
    if (isHakan) {
        const petInfo = (typeof currentPetStage === 'function') ? currentPetStage() : null;
        html += `<div class="home-top-row">`;
        if (streak.current >= 2) {
            html += `<div class="streak-banner">
                <span class="streak-flame">🔥</span>
                <span class="streak-count">${streak.current}</span>
                <span class="streak-label">day streak${streak.current === streak.longest ? ' — best!' : ''}</span>
            </div>`;
        }
        if (petInfo && petInfo.stage) {
            const outfits = (typeof loadPetOutfits === 'function') ? loadPetOutfits() : { equipped: {} };
            const eq = outfits.equipped || {};
            const hatStr = eq.hat ? (PET_OUTFITS.find((o) => o.id === eq.hat) || {}).emoji || '' : '';
            const accStr = eq.acc ? (PET_OUTFITS.find((o) => o.id === eq.acc) || {}).emoji || '' : '';
            const petState = (typeof loadPetState === 'function') ? loadPetState() : {};
            const petName = (petState.nickname || petInfo.pet.name.split(' ')[0]);
            html += `<button class="pet-badge" onclick="openPetPicker()" title="Tap to change your buddy">
                <span class="pet-badge-emoji">${hatStr}${petInfo.stage.emoji}${accStr}</span>
                <span class="pet-badge-name">${petName}</span>
            </button>`;
        }
        html += `<button class="trophy-btn" onclick="openTrophyRoom()">🏆 Trophies</button>`;
        html += `<button class="minigames-btn" onclick="openMiniGamesHub()">🎮 Games</button>`;
        html += `<button class="journey-btn" onclick="openProgressMap()">🗺️ Journey</button>`;
        html += `<button class="scrapbook-btn" onclick="openScrapbook()">📖 Stickers</button>`;
        html += `<button class="glossary-btn" onclick="openGlossary()">📚 Words</button>`;
        const sp = (typeof loadSoundProfile === 'function') ? loadSoundProfile() : 'cheerful';
        const spEmoji = sp === 'silent' ? '🤫' : sp === 'gentle' ? '🍃' : '🎉';
        html += `<button class="sound-btn" onclick="openSoundProfilePicker()" title="Sound: ${sp}">${spEmoji} Sound</button>`;
        html += `<button class="comfort-btn" onclick="openComfortPicker()" title="Text &amp; motion">🅰️ Comfort</button>`;
        html += `</div>`;
        // Module search
        html += `<div class="module-search-wrap">
            <input id="module-search" class="module-search" type="search"
                   placeholder="🔎 Search modules..." oninput="filterModules(this.value)" />
        </div>`;
    }

    // Problem of the Day card
    if (isHakan && typeof _potdToday === 'function') {
        const potd = _potdToday();
        const prob = POTD_POOL[potd.idx];
        if (prob) {
            html += `<button class="potd-card-home ${potd.solved ? 'potd-solved' : ''}" onclick="openProblemOfTheDay()">
                <div class="potd-card-label">🎯 Problem of the Day</div>
                <div class="potd-card-q">${potd.solved ? '✅ Solved! ' + prob.q : prob.q}</div>
                <div class="potd-card-prize">${potd.solved ? 'Come back tomorrow!' : 'Solve it for +5 💎'}</div>
            </button>`;
        }
    }

    // Daily quests panel
    if (isHakan && typeof loadDailyQuests === 'function') {
        const qs = loadDailyQuests();
        if (qs && qs.quests && qs.quests.length) {
            html += `<section class="quests-panel">
                <div class="qp-label">📋 Today's Quests</div>
                <div class="qp-list">`;
            for (const q of qs.quests) {
                const pct = Math.min(100, Math.round(((q.progress || 0) / q.target) * 100));
                const done = q.claimed;
                html += `<div class="qp-item ${done ? 'qp-done' : ''}">
                    <div class="qp-row1">
                        <span class="qp-text">${q.text}</span>
                        <span class="qp-robux">${done ? '✓' : '+' + q.robux + ' 💎'}</span>
                    </div>
                    <div class="qp-bar"><div class="qp-fill" style="width:${pct}%"></div></div>
                    <div class="qp-progress">${q.progress || 0} / ${q.target}</div>
                </div>`;
            }
            html += `</div></section>`;
        }
    }

    // "Practice This Again" — modules Hakan got 1 star on (struggled). Lower
    // priority than Today's Adventure but above the full grid so Hakan sees
    // them when he opens the app.
    if (isHakan && typeof findStrugglingModuleIds === 'function') {
        const strugglingIds = findStrugglingModuleIds();
        const struggling = strugglingIds.map((id) => MODULES_BY_ID[id]).filter(Boolean);
        if (struggling.length > 0) {
            html += `<section class="suggest-row suggest-struggle">
                <div class="sr-label">💪 Try These Again</div>
                <div class="sr-sub">You almost had these — let's get a star!</div>
                <div class="rp-row">
                    ${struggling.map((m) => `
                        <button class="rp-card rp-card-struggle" onclick="selectModule('${m.id}')" title="${m.title}">
                            <span class="rp-icon">${m.emoji}</span>
                            <span class="rp-title">${m.title}</span>
                        </button>
                    `).join('')}
                </div>
            </section>`;
        }
    }

    // "Review Time" — modules Hakan completed 7+ days ago. Spaced repetition.
    if (isHakan && typeof findReviewModuleIds === 'function') {
        const reviewIds = findReviewModuleIds();
        const review = reviewIds.map((id) => MODULES_BY_ID[id]).filter(Boolean);
        if (review.length > 0) {
            html += `<section class="suggest-row suggest-review">
                <div class="sr-label">🧠 Review Time</div>
                <div class="sr-sub">It's been a while — keep these fresh!</div>
                <div class="rp-row">
                    ${review.map((m) => `
                        <button class="rp-card rp-card-review" onclick="selectModule('${m.id}')" title="${m.title}">
                            <span class="rp-icon">${m.emoji}</span>
                            <span class="rp-title">${m.title}</span>
                        </button>
                    `).join('')}
                </div>
            </section>`;
        }
    }

    // "Recently Played" — last 5 modules Hakan opened (by lastVisited)
    if (isHakan) {
        const recent = Object.entries(visits)
            .map(([id, v]) => ({ id, ...v }))
            .sort((a, b) => (b.lastVisited || 0) - (a.lastVisited || 0))
            .slice(0, 5)
            .map((v) => MODULES_BY_ID[v.id])
            .filter(Boolean);
        if (recent.length > 0) {
            html += `<section class="recently-played">
                <div class="rp-label">⏱️ Recently Played</div>
                <div class="rp-row">
                    ${recent.map((m) => `
                        <button class="rp-card" onclick="selectModule('${m.id}')" title="${m.title}">
                            <span class="rp-icon">${m.emoji}</span>
                            <span class="rp-title">${m.title}</span>
                        </button>
                    `).join('')}
                </div>
            </section>`;
        }
    }

    // "Today's Adventure" banner — picks a deterministic-by-day uncompleted module
    if (isHakan) {
        const dayKey = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
        const seed = dayKey.split('').reduce((s, c) => s + c.charCodeAt(0), 0);
        const uncompleted = MODULES.filter((m) => !progress[m.id]);
        const pool = uncompleted.length ? uncompleted : MODULES;
        const todayMod = pool[seed % pool.length];
        if (todayMod) {
            html += `<section class="todays-adventure" onclick="selectModule('${todayMod.id}')">
                <div class="ta-label">🌟 Today's Adventure 🌟</div>
                <div class="ta-card">
                    <span class="ta-icon">${todayMod.emoji}</span>
                    <div class="ta-text">
                        <div class="ta-title">${todayMod.title}</div>
                        <div class="ta-desc">${todayMod.description}</div>
                    </div>
                    <span class="ta-arrow">→</span>
                </div>
            </section>`;
        }
    }

    let total = 0;
    for (const cat of CATEGORIES) {
        const mods = byCategory[cat.id];
        if (!mods || !mods.length) continue;
        mods.sort((a, b) => (a.order || 999) - (b.order || 999));

        // Category completion: all modules with ≥1 star
        const catCompleted = mods.every((m) => progress[m.id]);
        const catBadge = (catCompleted && isHakan) ? ' <span class="cat-badge">🏆</span>' : '';

        html += `<section class="m-category${catCompleted && isHakan ? ' m-category-done' : ''}">
            <h3 class="m-category-heading">${cat.emoji} ${cat.title}
                <span class="m-category-count">${mods.length}</span>${catBadge}
            </h3>
            <div class="m-category-grid">
                ${mods.map((m) => {
                    const p = progress[m.id];
                    const stars = p ? p.stars : 0;
                    const starsHtml = isHakan && stars > 0
                        ? `<span class="m-card-stars">${'⭐'.repeat(stars)}</span>`
                        : '';
                    const v = visits[m.id];
                    const visitCount = v ? v.count : 0;
                    const countHtml = isHakan && visitCount > 0
                        ? `<span class="m-card-count" title="Played ${visitCount} time${visitCount === 1 ? '' : 's'}">${visitCount}</span>`
                        : '';
                    const doneCls = stars > 0 ? ' m-card-done' : (visitCount > 0 ? ' m-card-visited' : '');
                    const newCls = (isHakan && visitCount === 0 && !p) ? ' m-card-new' : '';
                    const catCls = ` m-card-cat-${m.category || 'A'}`;
                    const newBadge = (isHakan && visitCount === 0 && !p)
                        ? '<span class="m-card-new-pill">NEW!</span>'
                        : '';
                    return `<button class="m-card${doneCls}${newCls}${catCls}" onclick="selectModule('${m.id}')">
                        ${countHtml}
                        ${starsHtml}
                        ${newBadge}
                        <span class="m-card-icon-wrap">
                            <span class="m-card-icon">${m.emoji}</span>
                        </span>
                        <span class="m-card-title">${m.title}</span>
                        <span class="m-card-desc">${m.description}</span>
                    </button>`;
                }).join('')}
            </div>
        </section>`;
        total += mods.length;
    }
    grid.innerHTML = html;

    // Show overall count + progress in the header
    const heading = document.querySelector('.modules-heading');
    if (heading) {
        if (isHakan && completedCount > 0) {
            heading.textContent = `Pick a Module — ${completedCount}/${total} done · ${totalStars}⭐`;
        } else {
            heading.textContent = `Pick a Module — ${total} skills to explore!`;
        }
    }
}

// ----------------------------------------------------------------------
// Module detail — three buttons: Lesson · Practice · Quiz
// ----------------------------------------------------------------------

// Open the visual progress map (Hakan's journey through the 14 categories)
function openProgressMap() {
    if (typeof playSound === 'function') playSound('click');
    const body = document.getElementById('progress-map-body');
    if (!body) return;
    const progress = (typeof loadAllProgress === 'function') ? loadAllProgress() : {};
    const stats = (typeof loadProblemStats === 'function') ? loadProblemStats() : {};
    const byCat = {};
    for (const cat of CATEGORIES) byCat[cat.id] = { cat, total: 0, started: 0, mastered: 0, stars: 0 };
    for (const m of MODULES) {
        const slot = byCat[m.category];
        if (!slot) continue;
        slot.total++;
        const p = progress[m.id];
        if (p) {
            slot.started++;
            slot.stars += p.stars || 0;
            if (p.stars === 3) slot.mastered++;
        }
    }
    // Total stars + total Robux for the page header
    const totalStars = Object.values(byCat).reduce((s, c) => s + c.stars, 0);
    const allTotal = Object.values(byCat).reduce((s, c) => s + c.total, 0);
    const allStarted = Object.values(byCat).reduce((s, c) => s + c.started, 0);

    // Math World themes per category — adds narrative flavor.
    const WORLD_THEMES = {
        A: { theme: 'Counting Forest 🌲', subtitle: 'where every tree wants to be counted' },
        B: { theme: 'Addition Town ➕',   subtitle: 'where numbers love to join hands' },
        C: { theme: 'Subtract Cove 🌊',   subtitle: 'where waves carry numbers away' },
        D: { theme: 'Place Value Mountain ⛰️', subtitle: 'home of tens and ones' },
        E: { theme: 'Compare Canyon ⚖️',  subtitle: 'where bigger and smaller meet' },
        F: { theme: 'Clock Tower 🕐',     subtitle: 'where time tells its story' },
        G: { theme: 'Coin Cave 🪙',       subtitle: 'glittering with pennies and dimes' },
        H: { theme: 'Shape Castle 🔷',    subtitle: 'built with every shape' },
        I: { theme: 'Sharing Garden 🥧',  subtitle: 'where pies split fair' },
        J: { theme: 'Measure Meadow 📏',  subtitle: 'rolling fields of length' },
        K: { theme: 'Pattern Path 🌀',    subtitle: 'the trail that never repeats' },
        L: { theme: 'Data Den 📊',        subtitle: 'home of bar graphs and tallies' },
        M: { theme: 'Story Square 📖',    subtitle: 'where Hakan\'s adventures unfold' },
        N: { theme: 'Mixed-Math Maze 🎯', subtitle: 'a little of everything' },
    };

    let html = `<div class="pm-summary">
        <div class="pm-summary-stat"><div class="pm-summary-num">${allStarted}/${allTotal}</div><div class="pm-summary-label">modules</div></div>
        <div class="pm-summary-stat"><div class="pm-summary-num">${totalStars}</div><div class="pm-summary-label">⭐ stars</div></div>
    </div>`;
    html += `<div class="pm-islands">`;
    let prevDone = true;
    for (const cat of CATEGORIES) {
        const c = byCat[cat.id];
        if (c.total === 0) continue;
        const startedPct = Math.round((c.started / c.total) * 100);
        const masteredPct = Math.round((c.mastered / c.total) * 100);
        const isMastered = c.mastered === c.total && c.total > 0;
        const isAlmost = !isMastered && masteredPct >= 80;
        const isInProgress = c.started > 0;
        const stateCls = isMastered ? 'pm-island-mastered' :
                         isAlmost ? 'pm-island-almost' :
                         isInProgress ? 'pm-island-progress' :
                         'pm-island-new';
        const world = WORLD_THEMES[cat.id] || { theme: cat.title, subtitle: '' };
        const badgeHtml = isMastered
            ? '<div class="pm-island-badge">🏆 Mastered!</div>'
            : (isAlmost ? '<div class="pm-island-badge pm-island-badge-almost">⚡ Almost!</div>' : '');
        html += `<div class="pm-island ${stateCls}">
            <div class="pm-island-emoji">${cat.emoji}</div>
            <div class="pm-island-name">${world.theme}</div>
            <div class="pm-island-sub">${world.subtitle}</div>
            <div class="pm-island-progress">${c.started}/${c.total} · ${c.stars}⭐</div>
            <div class="pm-island-bar">
                <div class="pm-island-bar-fill" style="width:${startedPct}%"></div>
                <div class="pm-island-bar-mastered" style="width:${masteredPct}%"></div>
            </div>
            ${badgeHtml}
        </div>`;
        prevDone = isInProgress;
    }
    html += `</div>`;
    body.innerHTML = html;
    showScreen('progress-map-screen');
}

// Filter visible module cards by a search query — matches title and description
// (case-insensitive substring). Hides empty categories.
function filterModules(query) {
    const q = (query || '').toLowerCase().trim();
    const cards = document.querySelectorAll('#module-grid .m-card');
    cards.forEach((card) => {
        const title = card.querySelector('.m-card-title');
        const desc  = card.querySelector('.m-card-desc');
        const text = ((title ? title.textContent : '') + ' ' + (desc ? desc.textContent : '')).toLowerCase();
        const show = !q || text.indexOf(q) >= 0;
        card.style.display = show ? '' : 'none';
    });
    // Hide categories with no visible cards
    document.querySelectorAll('#module-grid .m-category').forEach((cat) => {
        const anyVisible = cat.querySelectorAll('.m-card:not([style*="none"])').length > 0;
        cat.style.display = anyVisible ? '' : 'none';
    });
}

function selectModule(id) {
    if (typeof playSound === 'function') playSound('click');
    if (typeof initSpeechOnGesture === 'function') initSpeechOnGesture();
    const mod = MODULES_BY_ID[id];
    if (!mod) return;
    moduleState.moduleId = id;
    moduleState.activity = null;

    document.getElementById('module-detail-icon').textContent = mod.emoji;
    document.getElementById('module-detail-title').textContent = mod.title;
    document.getElementById('module-detail-desc').textContent = mod.description;

    const hasPractice = !!mod.practice || mod.kind === 'addsub' || mod.kind === 'factfamily';
    const hasQuiz     = !!mod.quiz     || mod.kind === 'addsub' || mod.kind === 'factfamily';
    document.getElementById('mod-lesson-btn').style.display   = mod.lesson ? '' : 'none';
    document.getElementById('mod-practice-btn').style.display = hasPractice ? '' : 'none';
    document.getElementById('mod-quiz-btn').style.display     = hasQuiz ? '' : 'none';

    // Adaptive review: show a "Review Missed" button if Hakan has wrongly-
    // answered problems on this module. Targeted re-exposure of the items
    // he struggled with — much higher learning value than random practice.
    const reviewBtn = document.getElementById('mod-review-btn');
    if (reviewBtn) {
        const isHakan = (typeof currentUser !== 'undefined' && currentUser === 'hakan');
        const missed = isHakan && typeof getMissedProblems === 'function'
            ? getMissedProblems(id) : [];
        if (missed.length > 0) {
            reviewBtn.style.display = '';
            const cnt = reviewBtn.querySelector('.act-sub');
            if (cnt) cnt.textContent = `${missed.length} missed`;
        } else {
            reviewBtn.style.display = 'none';
        }
    }

    showScreen('module-screen');
}

function startActivity(activity) {
    if (typeof playSound === 'function') playSound('click');
    const mod = MODULES_BY_ID[moduleState.moduleId];
    if (!mod) return;
    moduleState.activity = activity;

    // Track every activity start so the home grid can show a play-count
    // badge ("you've worked on this N times") and a Recently Played row.
    if (typeof currentUser !== 'undefined' && currentUser === 'hakan' &&
        typeof recordModuleVisit === 'function') {
        recordModuleVisit(moduleState.moduleId);
        if (typeof bumpQuests === 'function') {
            const claimed = bumpQuests('plays', 1);
            if (claimed.length && typeof showQuestClaimedToasts === 'function') showQuestClaimedToasts(claimed);
            if (activity === 'lesson') {
                const c2 = bumpQuests('lessons', 1);
                if (c2.length && typeof showQuestClaimedToasts === 'function') showQuestClaimedToasts(c2);
            }
        }
    }

    if (activity === 'lesson') {
        startLesson(mod);
        return;
    }

    if (activity === 'review') {
        startReviewActivity(mod);
        return;
    }

    const isPractice = (activity === 'practice');
    if (mod.kind === 'addsub') {
        // Delegate to existing addsub game (game.js).
        // gameMode is 'addition' | 'subtraction'. isPractice → 5 questions, no Robux.
        if (typeof startGame === 'function') startGame(mod.gameMode, isPractice);
        return;
    }
    if (mod.kind === 'factfamily') {
        if (typeof startFactFamilyGame === 'function') startFactFamilyGame(isPractice);
        return;
    }
    // Generic module: use the built-in problem flow
    startGenericProblems(mod, activity);
}

// ----------------------------------------------------------------------
// Lesson flow (used by every module)
// ----------------------------------------------------------------------

function startLesson(mod) {
    moduleState.lessonIndex = 0;
    showScreen('lesson-screen');
    renderLessonPage();
}

function renderLessonPage() {
    const mod = MODULES_BY_ID[moduleState.moduleId];
    if (!mod || !mod.lesson) return;
    const total = mod.lesson.length;
    const page = mod.lesson[moduleState.lessonIndex];
    const isFirst = moduleState.lessonIndex === 0;
    const isLast = moduleState.lessonIndex === total - 1;

    document.getElementById('lesson-title').textContent = page.title;
    const visualHost = document.getElementById('lesson-visual');
    visualHost.innerHTML = renderVisual(page.visual);
    document.getElementById('lesson-text').textContent = page.text;
    document.getElementById('lesson-caption').textContent = page.caption || '';
    document.getElementById('lesson-progress').textContent = `Lesson ${moduleState.lessonIndex + 1} / ${total}`;

    // Wire up any interactive primitives that just got inserted
    bindInteractivePrimitives(visualHost);

    const dots = [];
    for (let i = 0; i < total; i++) {
        dots.push(`<span class="dot ${i === moduleState.lessonIndex ? 'active' : (i < moduleState.lessonIndex ? 'done' : '')}"></span>`);
    }
    document.getElementById('lesson-dots').innerHTML = dots.join('');

    document.getElementById('lesson-back-btn').style.visibility = isFirst ? 'hidden' : '';
    const isDelegated = (mod.kind === 'addsub' || mod.kind === 'factfamily');
    document.getElementById('lesson-next-btn').textContent =
        isLast ? (isDelegated ? 'Done ✓' : "Let's Practice! 🎯") : 'Next ➡️';

    if (typeof speak === 'function') speak(page.text);

    // Story Mode: auto-advance after speech finishes
    if (moduleState.storyMode && !isLast) {
        scheduleStoryModeAdvance(page.text);
    }
}

// Story Mode: after a lesson page is spoken, wait an extra moment then
// advance to the next page automatically. Estimates speech duration from
// text length (since we don't get an "ended" callback from MP3 clip mode).
let __storyModeTimer = null;
function scheduleStoryModeAdvance(text) {
    if (__storyModeTimer) clearTimeout(__storyModeTimer);
    // ~70ms per character + 1.6s tail; capped 4s minimum, 14s max.
    const ms = Math.max(4000, Math.min(14000, (text || '').length * 70 + 1600));
    __storyModeTimer = setTimeout(() => {
        if (!moduleState.storyMode) return;
        nextLessonPage();
    }, ms);
}

function toggleStoryMode() {
    moduleState.storyMode = !moduleState.storyMode;
    const btn = document.getElementById('story-mode-btn');
    if (btn) {
        btn.classList.toggle('story-mode-on', moduleState.storyMode);
        btn.textContent = moduleState.storyMode ? '▶ Auto-Play On' : '▶ Auto-Play Off';
    }
    if (moduleState.storyMode) {
        // Kick off immediately on the current page
        const mod = MODULES_BY_ID[moduleState.moduleId];
        const page = mod && mod.lesson && mod.lesson[moduleState.lessonIndex];
        if (page) scheduleStoryModeAdvance(page.text);
    } else if (__storyModeTimer) {
        clearTimeout(__storyModeTimer);
        __storyModeTimer = null;
    }
}

// ----------------------------------------------------------------------
// Interactive lesson primitive event handling
// ----------------------------------------------------------------------
function bindInteractivePrimitives(host) {
    if (!host) return;
    const wrap = host.querySelector('[data-interactive]');
    if (!wrap) return;
    const kind = wrap.getAttribute('data-interactive');

    if (kind === 'tap-to-count' || kind === 'fill-ten-frame') {
        const target = parseInt(wrap.getAttribute('data-target'), 10) || 0;
        const buttons = wrap.querySelectorAll(kind === 'tap-to-count' ? '.ic-tap-emoji' : '.ic-tf-cell');
        const counter = wrap.querySelector('.ic-counter');
        let tapped = 0;
        buttons.forEach((b) => {
            b.addEventListener('click', () => {
                if (b.classList.contains('ic-tapped')) return;
                if (tapped >= target) return;
                b.classList.add('ic-tapped');
                tapped += 1;
                if (counter) counter.textContent = `${tapped} / ${target}`;
                if (typeof playSound === 'function') playSound('click');
                if (tapped === target) {
                    wrap.classList.add('ic-done');
                    if (counter) counter.textContent = `Done! 🎉`;
                    if (typeof playSound === 'function') playSound('correct');
                }
            });
        });
        return;
    }

    if (kind === 'tap-the-answer' || kind === 'tap-shape') {
        const buttons = wrap.querySelectorAll(kind === 'tap-the-answer' ? '.ic-tap-opt' : '.ic-tap-shape');
        buttons.forEach((b) => {
            b.addEventListener('click', () => {
                if (b.classList.contains('ic-locked')) return;
                const isCorrect = b.getAttribute('data-correct') === '1';
                if (isCorrect) {
                    b.classList.add('ic-correct', 'ic-locked');
                    buttons.forEach((x) => x.classList.add('ic-locked'));
                    if (typeof playSound === 'function') playSound('correct');
                } else {
                    b.classList.add('ic-wrong');
                    if (typeof playSound === 'function') playSound('wrong');
                    setTimeout(() => b.classList.remove('ic-wrong'), 600);
                }
            });
        });
        return;
    }

    if (kind === 'count-along') {
        const target = parseInt(wrap.getAttribute('data-target'), 10) || 0;
        const items = wrap.querySelectorAll('.ic-ca-emoji');
        const counter = wrap.querySelector('.ic-ca-num');
        const replay = wrap.querySelector('.ic-ca-replay');
        let timer = null;
        function play() {
            if (timer) { clearInterval(timer); timer = null; }
            items.forEach((it) => it.classList.remove('ic-ca-lit'));
            if (counter) counter.textContent = '0';
            let i = 0;
            timer = setInterval(() => {
                if (i >= target) {
                    clearInterval(timer); timer = null;
                    wrap.classList.add('ic-done');
                    if (typeof playSound === 'function') playSound('correct');
                    return;
                }
                items[i].classList.add('ic-ca-lit');
                i += 1;
                if (counter) counter.textContent = String(i);
                if (typeof playSound === 'function') playSound('click');
            }, 700);
        }
        if (replay) replay.addEventListener('click', play);
        // Auto-start on first render (kids don't need to find a button)
        setTimeout(play, 400);
        return;
    }

    if (kind === 'tap-numberline') {
        const buttons = wrap.querySelectorAll('.ic-nl-tick');
        buttons.forEach((b) => {
            b.addEventListener('click', () => {
                if (b.classList.contains('ic-locked')) return;
                const isCorrect = b.getAttribute('data-correct') === '1';
                if (isCorrect) {
                    b.classList.add('ic-correct', 'ic-locked');
                    buttons.forEach((x) => x.classList.add('ic-locked'));
                    wrap.classList.add('ic-done');
                    if (typeof playSound === 'function') playSound('correct');
                } else {
                    b.classList.add('ic-wrong');
                    if (typeof playSound === 'function') playSound('wrong');
                    setTimeout(() => b.classList.remove('ic-wrong'), 500);
                }
            });
        });
        return;
    }

    if (kind === 'find-mistake') {
        const buttons = wrap.querySelectorAll('.ic-fm-num');
        buttons.forEach((b) => {
            b.addEventListener('click', () => {
                if (b.classList.contains('ic-locked')) return;
                const isWrong = b.getAttribute('data-wrong') === '1';
                if (isWrong) {
                    b.classList.add('ic-correct', 'ic-locked');
                    buttons.forEach((x) => x.classList.add('ic-locked'));
                    wrap.classList.add('ic-done');
                    if (typeof playSound === 'function') playSound('correct');
                } else {
                    b.classList.add('ic-wrong');
                    if (typeof playSound === 'function') playSound('wrong');
                    setTimeout(() => b.classList.remove('ic-wrong'), 600);
                }
            });
        });
        return;
    }
}

function nextLessonPage() {
    if (typeof playSound === 'function') playSound('click');
    const mod = MODULES_BY_ID[moduleState.moduleId];
    if (!mod) return;
    if (moduleState.lessonIndex < mod.lesson.length - 1) {
        moduleState.lessonIndex++;
        renderLessonPage();
    } else {
        // End of lesson
        if (mod.kind === 'addsub' || mod.kind === 'factfamily') {
            // Delegated practice/quiz — return to module detail
            selectModule(mod.id);
        } else {
            startGenericProblems(mod, 'practice');
        }
    }
}

function prevLessonPage() {
    if (typeof playSound === 'function') playSound('click');
    if (moduleState.lessonIndex > 0) {
        moduleState.lessonIndex--;
        renderLessonPage();
    }
}

// ----------------------------------------------------------------------
// Generic practice/quiz flow
// ----------------------------------------------------------------------

function startGenericProblems(mod, activity) {
    moduleState.activity = activity;
    moduleState.problemIndex = 0;
    moduleState.answer = '';
    moduleState.score = 0;
    moduleState.streak = 0;
    moduleState.bestStreak = 0;
    moduleState.correct = 0;
    moduleState.sessionRobux = 0;
    moduleState.hintShown = false;
    moduleState.locked = false;
    showScreen('module-game-screen');
    renderModuleProblem();
}

// Build a review queue from problems Hakan got wrong, then run it as a
// practice-style session (with hints, no Robux).
function startReviewActivity(mod) {
    if (!mod) return;
    const missed = typeof getMissedProblems === 'function'
        ? getMissedProblems(mod.id) : [];
    if (missed.length === 0) {
        alert("Nice! No problems to review.");
        return;
    }
    // Pull the actual problem objects (clone so we don't mutate)
    const queue = [];
    for (const m of missed) {
        const src = (m.activity === 'practice' ? mod.practice : mod.quiz) || [];
        if (m.idx >= 0 && m.idx < src.length) queue.push(src[m.idx]);
    }
    if (queue.length === 0) {
        alert("Nice! No problems to review.");
        return;
    }
    // Store for clearing after completion
    moduleState._reviewSource = missed;
    moduleState._reviewQueue = queue;
    moduleState.activity = 'review';
    moduleState.problemIndex = 0;
    moduleState.answer = '';
    moduleState.score = 0;
    moduleState.streak = 0;
    moduleState.bestStreak = 0;
    moduleState.correct = 0;
    moduleState.sessionRobux = 0;
    moduleState.hintShown = false;
    moduleState.locked = false;
    showScreen('module-game-screen');
    renderModuleProblem();
}

function getCurrentProblems() {
    const mod = MODULES_BY_ID[moduleState.moduleId];
    if (!mod) return null;
    if (moduleState.activity === 'review') return moduleState._reviewQueue || [];
    return moduleState.activity === 'practice' ? mod.practice : mod.quiz;
}

function renderModuleProblem() {
    const mod = MODULES_BY_ID[moduleState.moduleId];
    const problems = getCurrentProblems();
    if (!problems || !problems.length) return;
    const p = problems[moduleState.problemIndex];
    const total = problems.length;

    moduleState.answer = '';
    moduleState.hintShown = false;
    moduleState.locked = false;

    document.getElementById('mg-question').textContent = p.prompt;
    document.getElementById('mg-visual').innerHTML = renderVisual(p.visual);
    document.getElementById('mg-answer').textContent = '';

    const phaseLabel =
        moduleState.activity === 'practice' ? '🎯 Practice' :
        moduleState.activity === 'review'   ? '🔁 Review'   : '⭐ Quiz';
    document.getElementById('mg-phase').textContent = `${mod.emoji} ${mod.title} — ${phaseLabel}`;
    document.getElementById('mg-progress-text').textContent = `${moduleState.problemIndex + 1} / ${total}`;
    document.getElementById('mg-progress-fill').style.width = `${(moduleState.problemIndex / total) * 100}%`;
    document.getElementById('mg-score').textContent = moduleState.score;
    document.getElementById('mg-streak').textContent = `🔥 ${moduleState.streak}`;

    // Robux
    const robuxDisplay = document.getElementById('mg-robux-display');
    if (typeof currentUser !== 'undefined' && currentUser === 'hakan') {
        robuxDisplay.style.display = '';
        const total = (typeof loadRobux === 'function' ? loadRobux() : 0);
        document.getElementById('mg-robux-game').textContent = total.toFixed(2);
    } else {
        robuxDisplay.style.display = 'none';
    }

    // Numeric vs choice vs new types (ordering / matching / fill-blanks)
    const numericPad = document.getElementById('mg-num-pad');
    const choicePad  = document.getElementById('mg-choice-pad');
    if (p.type === 'numeric') {
        numericPad.style.display = '';
        choicePad.style.display = 'none';
    } else if (p.type === 'choice') {
        numericPad.style.display = 'none';
        choicePad.style.display = '';
        choicePad.innerHTML = (p.choices || []).map((c, i) =>
            `<button class="m-choice" onclick="mgPickChoice(${i})">${c}</button>`
        ).join('');
    } else if (p.type === 'ordering' || p.type === 'matching' || p.type === 'fill-blanks') {
        // Special types fill the visual area entirely; numeric pad becomes a
        // "Check" button. Choice pad hidden.
        numericPad.style.display = 'none';
        choicePad.style.display = 'none';
        const visualHost = document.getElementById('mg-visual');
        if (p.type === 'ordering') {
            visualHost.innerHTML = renderOrderingProblem(p);
            bindOrderingProblem(visualHost, p);
        } else if (p.type === 'matching') {
            visualHost.innerHTML = renderMatchingProblem(p);
            bindMatchingProblem(visualHost, p);
        } else if (p.type === 'fill-blanks') {
            visualHost.innerHTML = renderFillBlanksProblem(p);
            bindFillBlanksProblem(visualHost, p);
        }
    } else {
        numericPad.style.display = '';
        choicePad.style.display = 'none';
    }

    // Hint button — available during practice AND review (review is just
    // practice on past mistakes; hints are even more important there).
    const hintBtn = document.getElementById('mg-hint-btn');
    if ((moduleState.activity === 'practice' || moduleState.activity === 'review') && p.hint) {
        hintBtn.style.display = '';
        hintBtn.classList.remove('exhausted');
    } else {
        hintBtn.style.display = 'none';
    }
    document.getElementById('mg-hint-text').textContent = '';

    if (typeof speak === 'function') speak(p.prompt);
}

function mgShowHint() {
    if ((moduleState.activity !== 'practice' && moduleState.activity !== 'review') || moduleState.hintShown) return;
    const p = getCurrentProblems()[moduleState.problemIndex];
    if (!p.hint) return;
    moduleState.hintShown = true;
    document.getElementById('mg-hint-btn').classList.add('exhausted');
    if (typeof speak === 'function') speak(p.hint);
    if (typeof playSound === 'function') playSound('click');
    // Typewriter reveal — feels more like guidance unfolding step by step
    // than a wall of text suddenly appearing.
    typewriterHint('💡 ' + p.hint, document.getElementById('mg-hint-text'));
    // Add a "Show Me" button that animates the solution if we can derive
    // it from the visual (two-digit-add, take-away).
    showSolutionButton(p);
}

// Small helper: types `text` into `el` one character at a time.
function typewriterHint(text, el) {
    if (!el) return;
    el.textContent = '';
    let i = 0;
    const speed = 22; // ms per character
    function tick() {
        if (i >= text.length) return;
        el.textContent = text.slice(0, ++i);
        setTimeout(tick, speed);
    }
    tick();
}

// Add a "Show Step-by-Step" button after the hint when the problem has a
// visual we know how to walk through. Cleared on the next problem.
function showSolutionButton(p) {
    const host = document.getElementById('mg-hint-text');
    if (!host) return;
    const v = p.visual || {};
    let canWalk = false;
    if (v.type === 'two-digit-add' || v.type === 'add-groups') canWalk = true;
    if (v.type === 'take-away') canWalk = true;
    if (v.type === 'two-ten-frames' && v.filledA != null && v.filledB != null) canWalk = true;
    if (!canWalk) return;

    const btn = document.createElement('button');
    btn.className = 'show-step-btn';
    btn.textContent = '🎬 Show me step-by-step';
    btn.onclick = () => playSolutionWalkthrough(p);
    host.appendChild(document.createElement('br'));
    host.appendChild(btn);
}

// Per-module worked-example scripts loaded at startup (see workedExamples.json).
// Each entry: { strategy, intro, steps, applyToVisual, example } for a module id.
let WORKED_EXAMPLES = {};
(async function loadWorkedExamples() {
    try {
        const res = await fetch('workedExamples.json?v=' + (typeof AUDIO_VERSION !== 'undefined' ? AUDIO_VERSION : 1));
        if (res.ok) WORKED_EXAMPLES = await res.json();
    } catch (e) { /* silent — feature falls back to generic walkthrough */ }
})();

// Animated walkthrough for the few visuals we know how to step through.
// Renders into the existing visual container with a temporary overlay.
function playSolutionWalkthrough(p) {
    const visualHost = document.getElementById('mg-visual');
    if (!visualHost) return;
    const v = p.visual || {};
    if (typeof playSound === 'function') playSound('click');

    // Per-module worked example takes priority — author-provided narration
    // tied to the lesson's primary strategy.
    const we = WORKED_EXAMPLES[moduleState.moduleId];
    if (we && Array.isArray(we.steps) && we.steps.length) {
        const overlay = document.createElement('div');
        overlay.className = 'walk-overlay';
        overlay.innerHTML = `<div class="walk-num"></div><div class="walk-step"></div>`;
        visualHost.appendChild(overlay);
        const numEl = overlay.querySelector('.walk-num');
        const stepEl = overlay.querySelector('.walk-step');
        if (we.intro) stepEl.textContent = we.intro;
        const result = we.example && (we.example.result != null ? we.example.result : we.example.answer);
        let i = 0;
        function tickStep() {
            if (i >= we.steps.length) {
                if (result != null) {
                    numEl.textContent = result;
                    if (we.example && we.example.a != null && we.example.b != null) {
                        const op = (we.strategy && we.strategy.indexOf('count-back') >= 0) ||
                                   (we.strategy && we.strategy.indexOf('take') >= 0)
                                   ? '−' : '+';
                        stepEl.textContent = `${we.example.a} ${op} ${we.example.b} = ${result} ✨`;
                    } else {
                        stepEl.textContent = `Answer: ${result} ✨`;
                    }
                    if (typeof playSound === 'function') playSound('correct');
                }
                setTimeout(() => overlay.remove(), 2400);
                return;
            }
            const s = we.steps[i++];
            stepEl.textContent = (typeof s === 'string') ? s : (s && s.text) || '';
            if (s && s.text) {
                const m = String(s.text).match(/\b(\d+)\b/);
                if (m) {
                    numEl.textContent = m[1];
                    numEl.classList.remove('walk-pop'); void numEl.offsetWidth;
                    numEl.classList.add('walk-pop');
                }
            }
            setTimeout(tickStep, 1200);
        }
        if (we.intro) setTimeout(tickStep, 1200); else tickStep();
        return;
    }

    // For "5 + 3" style problems, count up: 5 -> 6 -> 7 -> 8
    if (v.type === 'two-digit-add' || v.type === 'add-groups') {
        const a = v.a || 0, b = v.b || 0;
        const isAdd = (p.answer == null) ? true : (a + b === p.answer);
        if (!isAdd) return;
        let n = a;
        const target = a + b;
        const overlay = document.createElement('div');
        overlay.className = 'walk-overlay';
        overlay.innerHTML = `<div class="walk-num"></div><div class="walk-step"></div>`;
        visualHost.appendChild(overlay);
        const numEl = overlay.querySelector('.walk-num');
        const stepEl = overlay.querySelector('.walk-step');
        numEl.textContent = a;
        stepEl.textContent = `Start at ${a}`;
        let count = 0;
        function step() {
            if (count >= b) {
                stepEl.textContent = `${a} + ${b} = ${target} ✨`;
                if (typeof playSound === 'function') playSound('correct');
                setTimeout(() => overlay.remove(), 2400);
                return;
            }
            n += 1; count += 1;
            numEl.textContent = n;
            numEl.classList.remove('walk-pop');
            void numEl.offsetWidth;
            numEl.classList.add('walk-pop');
            stepEl.textContent = `Count on: ${n}`;
            setTimeout(step, 720);
        }
        setTimeout(step, 700);
        return;
    }

    // For "8 - 3" style: count down
    if (v.type === 'take-away') {
        const total = v.total || 0, taken = v.taken || 0;
        let n = total;
        const target = total - taken;
        const overlay = document.createElement('div');
        overlay.className = 'walk-overlay';
        overlay.innerHTML = `<div class="walk-num"></div><div class="walk-step"></div>`;
        visualHost.appendChild(overlay);
        const numEl = overlay.querySelector('.walk-num');
        const stepEl = overlay.querySelector('.walk-step');
        numEl.textContent = total;
        stepEl.textContent = `Start at ${total}`;
        let count = 0;
        function step() {
            if (count >= taken) {
                stepEl.textContent = `${total} − ${taken} = ${target} ✨`;
                if (typeof playSound === 'function') playSound('correct');
                setTimeout(() => overlay.remove(), 2400);
                return;
            }
            n -= 1; count += 1;
            numEl.textContent = n;
            numEl.classList.remove('walk-pop');
            void numEl.offsetWidth;
            numEl.classList.add('walk-pop');
            stepEl.textContent = `Take 1 away: ${n}`;
            setTimeout(step, 720);
        }
        setTimeout(step, 700);
        return;
    }

    // Two-ten-frames (make-10): split-and-fill animation (simplified text)
    if (v.type === 'two-ten-frames') {
        const a = v.filledA || 0, b = v.filledB || 0;
        const overlay = document.createElement('div');
        overlay.className = 'walk-overlay';
        overlay.innerHTML = `<div class="walk-step"></div>`;
        visualHost.appendChild(overlay);
        const stepEl = overlay.querySelector('.walk-step');
        const steps = [
            `Start: ${a} and ${b}`,
            `Take ${10 - a} from ${b} to fill the 10`,
            `Now: 10 and ${a + b - 10} more`,
            `${a} + ${b} = ${a + b} ✨`,
        ];
        let i = 0;
        function step() {
            if (i >= steps.length) {
                if (typeof playSound === 'function') playSound('correct');
                setTimeout(() => overlay.remove(), 2400);
                return;
            }
            stepEl.textContent = steps[i++];
            setTimeout(step, 1100);
        }
        step();
    }
}

function mgTypeNumber(d) {
    if (moduleState.locked) return;
    if (moduleState.answer.length < 3) {
        moduleState.answer += d;
        document.getElementById('mg-answer').textContent = moduleState.answer;
    }
}
function mgDeleteNumber() {
    if (moduleState.locked) return;
    moduleState.answer = moduleState.answer.slice(0, -1);
    document.getElementById('mg-answer').textContent = moduleState.answer;
}

function mgPickChoice(idx) {
    if (moduleState.locked) return;
    const p = getCurrentProblems()[moduleState.problemIndex];
    if (p.type !== 'choice') return;
    const correct = (idx === p.answerIndex);
    moduleState.answer = String(idx);
    if (correct) handleCorrect(); else handleWrong();
}

function mgCheckAnswer() {
    if (moduleState.locked || moduleState.answer === '') return;
    const p = getCurrentProblems()[moduleState.problemIndex];
    if (p.type === 'numeric') {
        const correct = (parseInt(moduleState.answer, 10) === p.answer);
        if (correct) handleCorrect(); else handleWrong();
    }
}

// ----------------------------------------------------------------------
// New problem types: ordering, matching, fill-blanks
// These render their full UI into the visual area; they auto-check on
// completion (no Check button needed) and call handleCorrect/handleWrong.
// ----------------------------------------------------------------------

function renderOrderingProblem(p) {
    const items = p.items || [];
    // Shuffle the display order deterministically per problem (so it's
    // not always in the correct order to start with).
    const idx = moduleState.problemIndex;
    const order = items.map((it, i) => ({ it, sortKey: (i * 13 + idx * 7) % 100 }))
        .sort((a, b) => a.sortKey - b.sortKey)
        .map((x) => x.it);
    const cells = order.map((it, i) => {
        const v = (it && it.value != null) ? it.value : it;
        const lbl = (it && it.label != null) ? it.label : String(v);
        return `<button class="m-ord-tile" data-value="${v}" data-label="${lbl}">${lbl}</button>`;
    }).join('');
    const slots = items.map(() => '<div class="m-ord-slot"></div>').join('');
    return `<div class="m-ord-wrap">
        <div class="m-ord-slots">${slots}</div>
        <div class="m-ord-tiles">${cells}</div>
        <div class="m-ord-status">Tap in order</div>
    </div>`;
}

function bindOrderingProblem(host, p) {
    const correctOrder = p.correctOrder || (p.items || []).map((it) => (it.value != null ? it.value : it));
    const tiles = host.querySelectorAll('.m-ord-tile');
    const slots = host.querySelectorAll('.m-ord-slot');
    const status = host.querySelector('.m-ord-status');
    let placed = 0;
    tiles.forEach((t) => {
        t.addEventListener('click', () => {
            if (t.classList.contains('m-ord-placed') || moduleState.locked) return;
            const val = parseFloat(t.getAttribute('data-value'));
            const slot = slots[placed];
            if (!slot) return;
            slot.textContent = t.getAttribute('data-label');
            slot.classList.add('m-ord-slot-filled');
            t.classList.add('m-ord-placed');
            placed += 1;
            if (typeof playSound === 'function') playSound('click');
            // Check the placement
            if (val !== correctOrder[placed - 1]) {
                slot.classList.add('m-ord-slot-wrong');
                if (typeof playSound === 'function') playSound('wrong');
                if (status) status.textContent = "Hmm, let's try again!";
                moduleState.answer = 'WRONG';
                setTimeout(() => handleWrong(), 600);
                return;
            }
            if (placed === slots.length) {
                if (status) status.textContent = "Perfect! ✨";
                moduleState.answer = 'OK';
                setTimeout(() => handleCorrect(), 600);
            }
        });
    });
}

function renderMatchingProblem(p) {
    const left = p.leftItems || [];
    const right = p.rightItems || [];
    // Shuffle right column
    const idx = moduleState.problemIndex;
    const rOrder = right.map((it, i) => ({ it, sortKey: (i * 19 + idx * 11) % 100 }))
        .sort((a, b) => a.sortKey - b.sortKey)
        .map((x) => x.it);
    const leftHtml = left.map((l) =>
        `<button class="m-match-tile m-match-left" data-val="${l}">${l}</button>`).join('');
    const rightHtml = rOrder.map((r) =>
        `<button class="m-match-tile m-match-right" data-val="${r}">${r}</button>`).join('');
    return `<div class="m-match-wrap">
        <div class="m-match-col">${leftHtml}</div>
        <div class="m-match-col">${rightHtml}</div>
        <div class="m-match-status">Tap one on each side to pair!</div>
    </div>`;
}

function bindMatchingProblem(host, p) {
    const pairs = (p.correctPairs || []).map((pp) =>
        Array.isArray(pp) ? pp : [pp.left, pp.right]);
    const leftTiles  = host.querySelectorAll('.m-match-left');
    const rightTiles = host.querySelectorAll('.m-match-right');
    const status     = host.querySelector('.m-match-status');
    let selected = null;
    let pairsLeft = pairs.length;

    function isValidPair(leftVal, rightVal) {
        return pairs.some((pp) =>
            String(pp[0]) === String(leftVal) && String(pp[1]) === String(rightVal));
    }
    function markUsed(leftVal, rightVal) {
        leftTiles.forEach((t) => {
            if (String(t.getAttribute('data-val')) === String(leftVal)) {
                t.classList.add('m-match-done');
            }
        });
        rightTiles.forEach((t) => {
            if (String(t.getAttribute('data-val')) === String(rightVal)) {
                t.classList.add('m-match-done');
            }
        });
        // Remove the pair from the pool so it can be reused (matching can have
        // duplicates e.g. 5+3 -> 8 and 4+4 -> 8). Splice the FIRST matching pair.
        const i = pairs.findIndex((pp) =>
            String(pp[0]) === String(leftVal) && String(pp[1]) === String(rightVal));
        if (i >= 0) pairs.splice(i, 1);
    }

    function onTileClick(t, side) {
        if (t.classList.contains('m-match-done') || moduleState.locked) return;
        if (!selected) {
            selected = { tile: t, side, val: t.getAttribute('data-val') };
            t.classList.add('m-match-sel');
            return;
        }
        // Already a selection — if it's the same side, switch selection
        if (selected.side === side) {
            selected.tile.classList.remove('m-match-sel');
            selected = { tile: t, side, val: t.getAttribute('data-val') };
            t.classList.add('m-match-sel');
            return;
        }
        // Different side — try to pair
        const leftVal  = selected.side === 'left' ? selected.val : t.getAttribute('data-val');
        const rightVal = selected.side === 'left' ? t.getAttribute('data-val') : selected.val;
        if (isValidPair(leftVal, rightVal)) {
            selected.tile.classList.remove('m-match-sel');
            t.classList.remove('m-match-sel');
            markUsed(leftVal, rightVal);
            selected = null;
            pairsLeft -= 1;
            if (typeof playSound === 'function') playSound('click');
            if (pairsLeft <= 0) {
                if (status) status.textContent = "All matched! ✨";
                moduleState.answer = 'OK';
                setTimeout(() => handleCorrect(), 600);
            }
        } else {
            t.classList.add('m-match-wrong');
            selected.tile.classList.add('m-match-wrong');
            if (typeof playSound === 'function') playSound('wrong');
            setTimeout(() => {
                t.classList.remove('m-match-wrong', 'm-match-sel');
                if (selected) selected.tile.classList.remove('m-match-wrong', 'm-match-sel');
                selected = null;
            }, 600);
            moduleState.answer = 'WRONG';
            setTimeout(() => handleWrong(), 700);
        }
    }
    leftTiles.forEach((t) => t.addEventListener('click', () => onTileClick(t, 'left')));
    rightTiles.forEach((t) => t.addEventListener('click', () => onTileClick(t, 'right')));
}

function renderFillBlanksProblem(p) {
    const seq = p.sequence || [];
    const cells = seq.map((s, i) => {
        if (s === '_' || s == null) {
            return `<button class="m-fb-blank" data-idx="${i}" data-val=""></button>`;
        }
        return `<span class="m-fb-num">${s}</span>`;
    }).join('<span class="m-fb-sep">,</span>');
    // Pick a digit pad of plausible candidates: all answers + 4 random nearby numbers
    const blanks = p.blanks || [];
    const pool = new Set(blanks.map(String));
    blanks.forEach((b) => {
        // Add a couple nearby numbers as distractors
        if (b - 1 >= 0) pool.add(String(b - 1));
        if (b + 1 <= 120) pool.add(String(b + 1));
    });
    // Pad with single-digit numbers up to 8 buttons
    let candidate = 0;
    while (pool.size < 8 && candidate < 20) {
        pool.add(String(candidate));
        candidate += 1;
    }
    const sorted = Array.from(pool).map(Number).sort((a, b) => a - b);
    const pad = sorted.map((n) =>
        `<button class="m-fb-pad-btn" data-num="${n}">${n}</button>`).join('');
    return `<div class="m-fb-wrap">
        <div class="m-fb-row">${cells}</div>
        <div class="m-fb-pad">${pad}</div>
        <div class="m-fb-status">Tap a blank, then tap the number!</div>
    </div>`;
}

function bindFillBlanksProblem(host, p) {
    const blanks = host.querySelectorAll('.m-fb-blank');
    const padButtons = host.querySelectorAll('.m-fb-pad-btn');
    const status = host.querySelector('.m-fb-status');
    let active = null;
    if (blanks.length) {
        blanks[0].classList.add('m-fb-blank-active');
        active = blanks[0];
    }
    blanks.forEach((b) => {
        b.addEventListener('click', () => {
            if (moduleState.locked) return;
            if (active) active.classList.remove('m-fb-blank-active');
            active = b;
            active.classList.add('m-fb-blank-active');
        });
    });
    padButtons.forEach((btn) => {
        btn.addEventListener('click', () => {
            if (moduleState.locked || !active) return;
            const n = btn.getAttribute('data-num');
            active.textContent = n;
            active.setAttribute('data-val', n);
            active.classList.remove('m-fb-blank-active');
            // Advance to next empty blank
            let nextBlank = null;
            blanks.forEach((b) => {
                if (b !== active && !nextBlank && !b.getAttribute('data-val')) nextBlank = b;
            });
            if (nextBlank) {
                active = nextBlank;
                active.classList.add('m-fb-blank-active');
            } else {
                // All filled — check answer
                const want = p.blanks || [];
                const blankIdxs = Array.from(blanks);
                let allRight = true;
                for (let i = 0; i < blankIdxs.length; i++) {
                    const val = parseInt(blankIdxs[i].getAttribute('data-val'), 10);
                    if (val !== want[i]) { allRight = false; break; }
                }
                if (allRight) {
                    if (status) status.textContent = "All right! ✨";
                    moduleState.answer = 'OK';
                    setTimeout(() => handleCorrect(), 600);
                } else {
                    blankIdxs.forEach((b, i) => {
                        if (parseInt(b.getAttribute('data-val'), 10) !== want[i]) {
                            b.classList.add('m-fb-blank-wrong');
                        }
                    });
                    moduleState.answer = 'WRONG';
                    if (typeof playSound === 'function') playSound('wrong');
                    setTimeout(() => handleWrong(), 700);
                }
            }
            if (typeof playSound === 'function') playSound('click');
        });
    });
}

function handleCorrect() {
    if (typeof playSound === 'function') playSound('correct');
    moduleState.streak++;
    moduleState.bestStreak = Math.max(moduleState.bestStreak, moduleState.streak);
    moduleState.correct++;
    moduleState.score += 10;

    if (moduleState.activity === 'quiz' && typeof currentUser !== 'undefined' && currentUser === 'hakan') {
        moduleState.sessionRobux += ROBUX_PER_QUIZ_CORRECT;
        if (typeof saveRobux === 'function' && typeof loadRobux === 'function') {
            saveRobux(loadRobux() + ROBUX_PER_QUIZ_CORRECT);
        }
    }

    // Per-problem struggle tracking (Hakan only — only counts the FIRST attempt
    // on each problem so we don't double-count after a wrong-then-correct).
    if (typeof currentUser !== 'undefined' && currentUser === 'hakan' &&
        typeof recordProblemAttempt === 'function' && !moduleState._countedThisProblem) {
        recordProblemAttempt(moduleState.moduleId, moduleState.activity,
                             moduleState.problemIndex, true);
        moduleState._countedThisProblem = true;
        if (typeof bumpQuests === 'function') {
            const claimed = bumpQuests('correct', 1);
            if (claimed.length && typeof showQuestClaimedToasts === 'function') showQuestClaimedToasts(claimed);
        }
    }

    const msg = (typeof MESSAGES !== 'undefined') ? randomChoice(MESSAGES.correct) : 'Great!';
    showMGFeedback('correct', msg);
    if (typeof speak === 'function') speak(msg);
    moduleState.locked = true;
    setTimeout(() => advanceModuleProblem(), 1500);
}

function handleWrong() {
    if (typeof playSound === 'function') playSound('wrong');
    moduleState.streak = 0;

    // Per-problem struggle tracking — record the first wrong attempt
    // (after that, additional retries don't change the stats).
    const isFirstWrong = !moduleState._countedThisProblem;
    if (typeof currentUser !== 'undefined' && currentUser === 'hakan' &&
        typeof recordProblemAttempt === 'function' && !moduleState._countedThisProblem) {
        recordProblemAttempt(moduleState.moduleId, moduleState.activity,
                             moduleState.problemIndex, false);
        moduleState._countedThisProblem = true;
    }

    const msg = (typeof MESSAGES !== 'undefined') ? randomChoice(MESSAGES.wrong) : 'Try again!';
    showMGFeedback('wrong', msg);
    if (typeof speak === 'function') speak(msg);
    moduleState.answer = '';
    document.getElementById('mg-answer').textContent = '';

    // In quiz/review, after the first wrong attempt also show the correct
    // answer gently so Hakan learns the right one. Auto-advances.
    if (isFirstWrong && (moduleState.activity === 'quiz' || moduleState.activity === 'review')) {
        const p = getCurrentProblems()[moduleState.problemIndex];
        if (p) showCorrectAnswerReveal(p);
        // Capture for end-of-session fact-family review.
        if (p && (p.type === 'addition' || p.type === 'subtraction')) {
            moduleState._missedFamilies = moduleState._missedFamilies || [];
            moduleState._missedFamilies.push({ type: p.type, a: p.a, b: p.b, answer: p.answer });
        }
    }
}

// Brief, kind reveal of the right answer after Hakan gets a quiz problem
// wrong. Auto-advances after a short pause so the flow keeps moving.
function showCorrectAnswerReveal(p) {
    if (moduleState._answerRevealActive) return;
    moduleState._answerRevealActive = true;
    moduleState.locked = true;
    const visualHost = document.getElementById('mg-visual');
    if (!visualHost) return;
    let answerText;
    if (p.type === 'numeric') {
        answerText = String(p.answer);
    } else if (p.type === 'choice') {
        answerText = (p.choices && p.choices[p.answerIndex]) || '';
    } else {
        answerText = ''; // ordering/matching/fill-blanks already auto-advance
    }
    if (!answerText) { moduleState._answerRevealActive = false; moduleState.locked = false; return; }
    const overlay = document.createElement('div');
    overlay.className = 'answer-reveal';
    overlay.innerHTML = `
        <div class="ar-label">The answer is</div>
        <div class="ar-value">${answerText}</div>
        <div class="ar-sub">Don't worry, Hakan — you'll get the next one! 💪</div>
    `;
    visualHost.appendChild(overlay);
    setTimeout(() => {
        try { overlay.remove(); } catch (e) {}
        moduleState._answerRevealActive = false;
        moduleState.locked = false;
        advanceModuleProblem();
    }, 2200);
}

function showMGFeedback(kind, msg) {
    const overlay = document.getElementById('mg-feedback-overlay');
    const content = document.getElementById('mg-feedback-content');
    if (!overlay || !content) return;
    content.textContent = (kind === 'correct' ? '✅ ' : '🤔 ') + msg;
    content.className = 'feedback-content ' + (kind === 'correct' ? 'fb-correct' : 'fb-wrong');
    overlay.classList.remove('hidden');
    setTimeout(() => overlay.classList.add('hidden'), 1200);
}

function advanceModuleProblem() {
    moduleState.locked = false;
    moduleState.problemIndex++;
    moduleState._countedThisProblem = false;     // reset for next problem
    const total = getCurrentProblems().length;
    if (moduleState.problemIndex >= total) {
        showModuleResults();
    } else {
        renderModuleProblem();
    }
}

// Build a 3-step fact-family review from a missed add/sub problem and run
// it as a guided popup. Each step asks one of the family's missing pieces.
function offerFactFamilyReview(miss) {
    if (!miss) return;
    // Compute the three parts of the family (a, b, c=a+b).
    const c = (miss.type === 'addition') ? miss.answer : miss.a;
    const a = (miss.type === 'addition') ? miss.a : (miss.a - miss.b);
    const b = (miss.type === 'addition') ? miss.b : miss.b;
    if ([a, b, c].some((v) => !Number.isFinite(v) || v < 0)) return;
    // Don't loop on the exact missed problem; pick the three siblings.
    const family = [
        { q: `${b} + ${a} = ?`, ans: c },
        { q: `${c} - ${a} = ?`, ans: b },
        { q: `${c} - ${b} = ?`, ans: a },
    ];
    let step = 0;
    const overlay = document.createElement('div');
    overlay.className = 'potd-overlay ff-overlay';
    function render() {
        const cur = family[step];
        overlay.innerHTML = `<div class="potd-card ff-card">
            <h2>🧩 Fact Family Boost</h2>
            <div class="ff-sub">When you know one, you know them all!</div>
            <div class="ff-progress">Step ${step + 1} of ${family.length}</div>
            <div class="potd-question">${cur.q}</div>
            <input type="number" class="potd-input" autocomplete="off" inputmode="numeric" />
            <div class="potd-actions">
                <button class="potd-check">Check</button>
                <button class="ff-skip">Skip</button>
            </div>
            <div class="potd-feedback"></div>
        </div>`;
        const input = overlay.querySelector('.potd-input');
        const fb = overlay.querySelector('.potd-feedback');
        const submit = () => {
            const val = parseInt(input.value, 10);
            if (Number.isNaN(val)) return;
            if (val === cur.ans) {
                fb.innerHTML = `<div class="potd-correct">✨ Yes! ${cur.q.replace('?', cur.ans)}</div>`;
                if (typeof playSound === 'function') playSound('correct');
                setTimeout(() => {
                    step++;
                    if (step >= family.length) {
                        // Reward Hakan: +3 robux for completing review.
                        if (typeof saveRobux === 'function' && typeof loadRobux === 'function') {
                            saveRobux(loadRobux() + 3);
                        }
                        overlay.innerHTML = `<div class="potd-card ff-card">
                            <h2>🌟 Family Mastered!</h2>
                            <div class="ff-sub">Great work, Hakan — +3 💎</div>
                            <button class="potd-close">Done</button>
                        </div>`;
                        overlay.querySelector('.potd-close').addEventListener('click', () => overlay.remove());
                    } else {
                        render();
                    }
                }, 900);
            } else {
                fb.innerHTML = `<div class="potd-wrong">Hint: ${cur.q.replace('?', cur.ans)}. Try entering ${cur.ans}.</div>`;
                if (typeof playSound === 'function') playSound('wrong');
            }
        };
        overlay.querySelector('.potd-check').addEventListener('click', submit);
        overlay.querySelector('.ff-skip').addEventListener('click', () => overlay.remove());
        input.addEventListener('keydown', (e) => { if (e.key === 'Enter') submit(); });
        setTimeout(() => input.focus(), 50);
    }
    overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.remove(); });
    document.body.appendChild(overlay);
    render();
}

function showModuleResults() {
    const mod = MODULES_BY_ID[moduleState.moduleId];
    const total = getCurrentProblems().length;
    const accuracy = moduleState.correct / total;
    const stars = accuracy >= 0.9 ? 3 : accuracy >= 0.7 ? 2 : 1;
    const isQuiz = moduleState.activity === 'quiz';

    // Save progress on quiz completion (Hakan only — keep Koray's runs untracked)
    if (isQuiz && typeof currentUser !== 'undefined' && currentUser === 'hakan') {
        if (typeof saveModuleProgress === 'function') {
            saveModuleProgress(moduleState.moduleId, stars);
        }
        // Bump quests: stars, perfects
        if (typeof bumpQuests === 'function') {
            const a = bumpQuests('stars', stars);
            const b = stars === 3 ? bumpQuests('perfect', 1) : [];
            const all = [].concat(a, b);
            if (all.length && typeof showQuestClaimedToasts === 'function') showQuestClaimedToasts(all);
        }
        // Check for newly-earned badges and show toasts
        if (typeof checkAndAwardBadges === 'function') {
            const earned = checkAndAwardBadges();
            if (earned && earned.length && typeof showBadgeToasts === 'function') {
                showBadgeToasts(earned);
            }
        }
    }

    // After a review session: clear the reviewed problems so they don't keep
    // surfacing. (If Hakan got them right this time, that's the goal of review.
    // If he got them wrong AGAIN, he'll re-enter the queue next session.)
    if (moduleState.activity === 'review' && typeof clearReviewedProblems === 'function') {
        clearReviewedProblems(moduleState.moduleId, moduleState._reviewSource || []);
    }

    const isReview = moduleState.activity === 'review';
    document.getElementById('results-title').textContent =
        isQuiz   ? `🎉 Quiz Complete! 🎉` :
        isReview ? `🔁 Review Complete! 🎉` :
                   `🎯 Practice Complete!`;

    // Mascot dialogue — encouraging message tailored to score
    const mascotMsg =
        stars === 3 ? "WOW Hakan, you're a math champion! 🏆" :
        stars === 2 ? "Great job, Hakan! Almost a perfect score! ⭐" :
        accuracy >= 0.5 ? "Nice try, Hakan! Practice makes progress! 💪" :
        "Don't worry, Hakan — every try makes you smarter! 🌱";
    const dialogueEl = document.getElementById('results-mascot-dialogue');
    if (dialogueEl) dialogueEl.textContent = mascotMsg;
    document.getElementById('final-score').textContent = moduleState.score;
    document.getElementById('final-correct').textContent = `${moduleState.correct} / ${total}`;
    document.getElementById('final-streak').textContent = moduleState.bestStreak;
    document.getElementById('star-rating').innerHTML = '⭐'.repeat(stars) + '<span class="dim-star">⭐</span>'.repeat(3 - stars);

    if (isQuiz && typeof currentUser !== 'undefined' && currentUser === 'hakan' && moduleState.sessionRobux > 0) {
        document.getElementById('robux-results').style.display = '';
        document.getElementById('robux-session').textContent = moduleState.sessionRobux.toFixed(2);
        document.getElementById('robux-total-result').textContent = (typeof loadRobux === 'function' ? loadRobux() : 0).toFixed(2);
    } else {
        document.getElementById('robux-results').style.display = 'none';
    }

    // Set state.currentModule for the recap/next-up panels rendered by showResults.
    if (typeof state !== 'undefined' && mod) state.currentModule = mod;
    if (typeof _renderResultsRecap === 'function') _renderResultsRecap();

    showScreen('results-screen');

    // Fact-family auto-review: after the results land, if Hakan missed any
    // add/sub problems, offer a quick family review.
    if (typeof currentUser !== 'undefined' && currentUser === 'hakan' &&
        moduleState._missedFamilies && moduleState._missedFamilies.length) {
        const fam = moduleState._missedFamilies[0];
        moduleState._missedFamilies = [];
        setTimeout(() => offerFactFamilyReview(fam), 1800);
    }

    // After Practice, the "Play Again" button becomes "Take the Quiz!" so
    // the natural progression is practice → quiz. After the Quiz it just
    // restarts the quiz.
    const playBtn = document.querySelector('.play-again-btn');
    if (playBtn) {
        if (moduleState.activity === 'practice') {
            playBtn.innerHTML = '⭐ Take the Quiz!';
            window.__lastModuleStarter = function () { startGenericProblems(mod, 'quiz'); };
        } else {
            playBtn.innerHTML = '🔄 Play Again';
            window.__lastModuleStarter = function () { startGenericProblems(mod, 'quiz'); };
        }
    } else {
        window.__lastModuleStarter = function () { startGenericProblems(mod, moduleState.activity); };
    }
}

// ----------------------------------------------------------------------
// On page load, populate the module grid. Scripts are at the end of
// body, so the DOM is already parsed by the time this runs.
// ----------------------------------------------------------------------
function _hideAppSplash() {
    const el = document.getElementById('app-splash');
    if (!el) return;
    el.classList.add('splash-hide');
    setTimeout(() => { try { el.remove(); } catch (e) {} }, 500);
}
function _bootHome() {
    if (typeof applyComfortSettings === 'function') applyComfortSettings();
    renderHomeModules();
    // Give the home screen one frame to paint, then fade splash out.
    requestAnimationFrame(() => requestAnimationFrame(_hideAppSplash));
}
// Safety: never let the splash linger more than 2.5s even if something
// fails to load — Hakan should never see a blank wall.
setTimeout(_hideAppSplash, 2500);

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _bootHome);
} else {
    _bootHome();
}
